package com.citacloud.springboot.contacloud.app.models;
import jakarta.persistence.*;import java.time.*;import java.util.UUID;
@Entity @Table(name="inventory_physical_count") public class ConteoFisico{
 @Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="tenant_id",nullable=false,updatable=false)private UUID tenantId;@Column(name="empresa_id",nullable=false,updatable=false)private UUID empresaId;
 @Column(name="count_number",nullable=false,updatable=false)private String numero;@Column(name="count_date",nullable=false)private LocalDate fecha;@Column(name="warehouse_id",nullable=false)private UUID almacenId;@Column(name="category_id")private UUID categoriaId;
 @Enumerated(EnumType.STRING)@Column(name="count_type",nullable=false)private TipoConteoFisico tipo;@Enumerated(EnumType.STRING)@Column(name="count_mode",nullable=false)private ModoConteoFisico modo;@Column(name="reference")private String referencia;@Column(name="notes")private String observacion;@Enumerated(EnumType.STRING)@Column(nullable=false)private EstadoConteoFisico status;
 @Column(name="warehouse_name_snapshot")private String almacenHistorico;@Column(name="branch_name_snapshot")private String sucursalHistorica;
 @Column(name="started_at")private OffsetDateTime iniciadoEn;@Column(name="started_by")private UUID iniciadoPor;@Column(name="finished_at")private OffsetDateTime finalizadoEn;@Column(name="finished_by")private UUID finalizadoPor;@Column(name="confirmed_at")private OffsetDateTime confirmadoEn;@Column(name="confirmed_by")private UUID confirmadoPor;@Column(name="confirmed_by_name_snapshot")private String confirmadoPorNombre;@Column(name="cancelled_at")private OffsetDateTime anuladoEn;@Column(name="cancelled_by")private UUID anuladoPor;@Column(name="cancellation_reason")private String motivoAnulacion;
 @Column(name="created_at",insertable=false,updatable=false)private OffsetDateTime creadoEn;@Column(name="created_by",nullable=false,updatable=false)private UUID creadoPor;@Column(name="updated_at",insertable=false)private OffsetDateTime actualizadoEn;@Column(name="updated_by",nullable=false)private UUID actualizadoPor;@Version private long version;
 @ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="warehouse_id",insertable=false,updatable=false)private Almacen almacen;
 protected ConteoFisico(){}public ConteoFisico(UUID t,UUID e,String n,LocalDate f,Almacen a,UUID c,TipoConteoFisico tipo,ModoConteoFisico modo,String r,String o,UUID u){tenantId=t;empresaId=e;numero=n;fecha=f;almacenId=a.getId();categoriaId=c;this.tipo=tipo;this.modo=modo;referencia=r;observacion=o;status=EstadoConteoFisico.DRAFT;creadoPor=u;actualizadoPor=u;almacen=a;}
 public void actualizar(LocalDate f,Almacen a,UUID c,TipoConteoFisico t,ModoConteoFisico m,String r,String o,UUID u){if(status!=EstadoConteoFisico.DRAFT)throw new IllegalStateException("Solo se puede editar un conteo en borrador.");fecha=f;almacenId=a.getId();categoriaId=c;tipo=t;modo=m;referencia=r;observacion=o;actualizadoPor=u;almacen=a;}
 public void iniciar(UUID u){if(status!=EstadoConteoFisico.DRAFT)throw new IllegalStateException("Solo se puede iniciar un conteo en borrador.");status=EstadoConteoFisico.IN_PROGRESS;iniciadoEn=OffsetDateTime.now();iniciadoPor=u;almacenHistorico=almacen.getNombre();sucursalHistorica=almacen.getSucursal().getNombre();actualizadoPor=u;}
 public void finalizar(UUID u){if(status!=EstadoConteoFisico.IN_PROGRESS)throw new IllegalStateException("El conteo no está en captura.");status=EstadoConteoFisico.PENDING_CONFIRMATION;finalizadoEn=OffsetDateTime.now();finalizadoPor=u;actualizadoPor=u;}
 public void confirmar(UUID u,String nombre){if(status!=EstadoConteoFisico.PENDING_CONFIRMATION)throw new IllegalStateException("El conteo no está pendiente de confirmación.");status=EstadoConteoFisico.CONFIRMED;confirmadoEn=OffsetDateTime.now();confirmadoPor=u;confirmadoPorNombre=nombre;actualizadoPor=u;}
 public void anular(String motivo,UUID u){if(status==EstadoConteoFisico.CONFIRMED)throw new IllegalStateException("Un conteo confirmado no puede anularse.");status=EstadoConteoFisico.CANCELLED;anuladoEn=OffsetDateTime.now();anuladoPor=u;motivoAnulacion=motivo;actualizadoPor=u;}@PreUpdate void marca(){actualizadoEn=OffsetDateTime.now();}
 public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public UUID getEmpresaId(){return empresaId;}public String getNumero(){return numero;}public LocalDate getFecha(){return fecha;}public UUID getAlmacenId(){return almacenId;}public UUID getCategoriaId(){return categoriaId;}public TipoConteoFisico getTipo(){return tipo;}public ModoConteoFisico getModo(){return modo;}public String getReferencia(){return referencia;}public String getObservacion(){return observacion;}public EstadoConteoFisico getEstado(){return status;}public String getAlmacenHistorico(){return almacenHistorico;}public String getSucursalHistorica(){return sucursalHistorica;}public OffsetDateTime getIniciadoEn(){return iniciadoEn;}public OffsetDateTime getFinalizadoEn(){return finalizadoEn;}public OffsetDateTime getConfirmadoEn(){return confirmadoEn;}public String getConfirmadoPorNombre(){return confirmadoPorNombre;}public OffsetDateTime getAnuladoEn(){return anuladoEn;}public String getMotivoAnulacion(){return motivoAnulacion;}public long getVersion(){return version;}public Almacen getAlmacen(){return almacen;}
}
